import React, { useState, useMemo, useEffect } from 'react';
import {
  Box,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TableSortLabel,
  TablePagination,
  Checkbox,
  TextField,
  InputAdornment,
  IconButton,
  Tooltip,
  Typography,
  Button,
  Menu,
  MenuItem,
  CircularProgress,
  alpha,
  Chip,
  Badge,
  useTheme,
  useMediaQuery,
  Divider,
  FormControl,
  InputLabel,
  Select,
  OutlinedInput,
  FormControlLabel,
  Checkbox as MuiCheckbox,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Tabs,
  Tab,
  Grid,
  Card,
  CardContent,
  CardActionArea,
  CardActions,
  Collapse,
  ButtonGroup
} from '@mui/material';
import { useCustomViews } from '../CustomViews/CustomViews';
import {
  Search as SearchIcon,
  FilterList as FilterListIcon,
  MoreVert as MoreVertIcon,
  ViewColumn as ViewColumnIcon,
  Delete as DeleteIcon,
  Edit as EditIcon,
  Refresh as RefreshIcon,
  Check as CheckIcon,
  Clear as ClearIcon,
  ArrowDropDown as ArrowDropDownIcon,
  Save as SaveIcon,
  Close as CloseIcon,
} from '@mui/icons-material';
import { visuallyHidden } from '@mui/utils';
import PropTypes from 'prop-types';
import { format, isSameDay } from 'date-fns';

const DataTable = ({
  columns,
  data,
  onRowClick,
  onEdit,
  onDelete,
  onRefresh,
  onSelectionChange,
  onBulkAction,
  loading = false,
  title = '',
  showSearch = true,
  showToolbar = true,
  showPagination = true,
  searchText: externalSearchText,
  onSearchChange,
  filters: externalFilters = {},
  onFilterChange,
  selectedRows: externalSelectedRows = [],
  dateRange,
  onDateRangeChange,
  bulkActions = [],
  viewType = 'default',
  onViewChange,
  onSaveView,
  onDeleteView,
  onSetDefaultView,
  customViews = [],
  currentView = null,
  setCurrentView = () => {}
}) => {
  const tableRef = useRef(null);
  const [selected, setSelected] = useState([]);
  const [order, setOrder] = useState('asc');
  const [orderBy, setOrderBy] = useState('');
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [searchText, setSearchText] = useState('');
  const [filters, setFilters] = useState({});
  const [anchorEl, setAnchorEl] = useState(null);
  const [columnMenuEl, setColumnMenuEl] = useState(null);
  const [visibleColumns, setVisibleColumns] = useState(
    columns.reduce((acc, col) => ({ ...acc, [col.field]: true }), {})
  );
  const [showFilters, setShowFilters] = useState(false);
  const [showSaveViewDialog, setShowSaveViewDialog] = useState(false);
  const [viewName, setViewName] = useState('');
  const [isPublicView, setIsPublicView] = useState(false);
  const [activeFilterTab, setActiveFilterTab] = useState(0);
  const [columnMenuAnchor, setColumnMenuAnchor] = useState(null);

  // Handle sort
  const handleRequestSort = (property) => {
    const isAsc = orderBy === property && order === 'asc';
    setOrder(isAsc ? 'desc' : 'asc');
    setOrderBy(property);
    // Reset to first page when sort changes
    setPage(0);
  };

  // Handle select all
  const handleSelectAllClick = (event) => {
    if (event.target.checked) {
      const newSelected = data.map((row) => row.id);
      setSelected(newSelected);
      onSelectionChange?.(newSelected);
      return;
    }
    setSelected([]);
    onSelectionChange?.([]);
  };

  // Handle select one
  const handleClick = (event, id) => {
    const selectedIndex = selected.indexOf(id);
    let newSelected = [];

    if (selectedIndex === -1) {
      newSelected = [...selected, id];
    } else if (selectedIndex === 0) {
      newSelected = selected.slice(1);
    } else if (selectedIndex === selected.length - 1) {
      newSelected = selected.slice(0, -1);
    } else if (selectedIndex > 0) {
      newSelected = [
        ...selected.slice(0, selectedIndex),
        ...selected.slice(selectedIndex + 1),
      ];
    }

    setSelected(newSelected);
    onSelectionChange?.(newSelected);
  };

  // Handle filter change
  const handleFilterChange = (field, value) => {
    const newFilters = { ...filters, [field]: value };
    if (onFilterChange) {
      onFilterChange(newFilters);
    } else {
      setFilters(newFilters);
    }

    // Reset to first page when filters change
    setPage(0);
  };

  // Handle column visibility toggle
  const toggleColumn = (field) => {
    setVisibleColumns(prev => ({
      ...prev,
      [field]: !prev[field]
    }));
  };

  // Process data with sorting and filtering
  const activeFilters = useMemo(() => {
    return externalFilters !== undefined ? externalFilters : filters;
  }, [externalFilters, filters]);

  const activeSearchText = useMemo(() => {
    return externalSearchText !== undefined ? externalSearchText : searchText;
  }, [externalSearchText, searchText]);

  const selectedRows = useMemo(() => {
    return externalSelectedRows !== undefined ? externalSelectedRows : selected;
  }, [externalSelectedRows, selected]);

  const filteredData = useMemo(() => {
    return data.filter((row) => {
      // Apply search text filter
      if (activeSearchText) {
        const searchLower = activeSearchText.toLowerCase();
        const searchableFields = Object.entries(row)
          .filter(([key]) => {
            // Skip filtering on columns that are not visible or don't exist in columns definition
            const column = columns.find(col => col.field === key);
            return column && visibleColumns[key] !== false;
          })
          .map(([_, value]) => String(value || '').toLowerCase())
          .join(' ');

        if (!searchableFields.includes(searchLower)) {
          return false;
        }
      }

      // Apply column filters
      for (const [key, value] of Object.entries(activeFilters)) {
        if (value === undefined || value === null || value === '') continue;

        const column = columns.find(col => col.field === key);
        if (!column) continue;

        // Handle different filter types
        if (column.filterType === 'select') {
          if (row[key] !== value) return false;
        } else if (column.filterType === 'date') {
          const rowDate = new Date(row[key]);
          const filterDate = new Date(value);

          if (isNaN(rowDate.getTime())) return false;

          if (column.filterOperator === 'before' && rowDate > filterDate) return false;
          if (column.filterOperator === 'after' && rowDate < filterDate) return false;
          if (column.filterOperator === 'on' && !isSameDay(rowDate, filterDate)) return false;
        } else if (column.filterType === 'range') {
          const rowValue = parseFloat(row[key]);
          const [min, max] = value;

          if (isNaN(rowValue)) return false;
          if (min !== undefined && rowValue < min) return false;
          if (max !== undefined && rowValue > max) return false;
        } else if (column.filterType === 'custom' && column.customFilter) {
          if (!column.customFilter(value, row)) return false;
        } else {
          // Default filter (exact match)
          if (String(row[key]).toLowerCase() !== String(value).toLowerCase()) {
            return false;
          }
        }
      }

      return true;
    });
  }, [data, activeSearchText, activeFilters, columns, visibleColumns]);

  const sortedData = useMemo(() => {
    if (!orderBy) return filteredData;

    return [...filteredData].sort((a, b) => {
      // Handle nested properties with dot notation (e.g., 'user.name')
      const getNestedValue = (obj, path) => {
        return path.split('.').reduce((o, p) => o?.[p], obj);
      };

      let aValue = getNestedValue(a, orderBy) ?? a[orderBy];
      let bValue = getNestedValue(b, orderBy) ?? b[orderBy];

      // Handle date sorting
      if (aValue instanceof Date || (typeof aValue === 'string' && !isNaN(Date.parse(aValue)))) {
        aValue = new Date(aValue);
        bValue = new Date(bValue);
      }

      if (aValue < bValue) {
        return order === 'asc' ? -1 : 1;
      }
      if (aValue > bValue) {
        return order === 'asc' ? 1 : -1;
      }
      return 0;
    });
  }, [filteredData, order, orderBy]);

  const paginatedData = useMemo(() => {
    if (!showPagination) return sortedData;
    const startIndex = page * rowsPerPage;
    return sortedData.slice(startIndex, startIndex + rowsPerPage);
  }, [sortedData, page, rowsPerPage, showPagination]);

  // Handle view save
  const handleSaveView = () => {
    const viewData = {
      name: viewName,
      filters: { ...activeFilters },
      sort: { order, orderBy },
      columns: { ...visibleColumns },
      isPublic: isPublicView,
      searchText: activeSearchText
    };

    if (onSaveView) {
      onSaveView(viewData);
    }

    setShowSaveViewDialog(false);
    setViewName('');
  };

  // Handle view apply
  const handleApplyView = (view) => {
    if (view.filters && onFilterChange) {
      onFilterChange(view.filters);
    }

    if (view.sort) {
      setOrder(view.sort.order);
      setOrderBy(view.sort.orderBy);
    }

    if (view.columns) {
      setVisibleColumns(view.columns);
    }

    if (view.searchText !== undefined && onSearchChange) {
      onSearchChange(view.searchText);
    } else if (view.searchText !== undefined) {
      setSearchText(view.searchText);
    }

    // Reset to first page when applying a view
    setPage(0);

    if (onViewChange) {
      onViewChange(view);
    }
  };

  // Handle filter tab change
  const handleFilterTabChange = (event, newValue) => {
    setActiveFilterTab(newValue);
  };

  // Handle search
  const handleSearch = (event) => {
    const value = event.target.value;
    if (onSearchChange) {
      onSearchChange(value);
    } else {
      setSearchText(value);
    }
    // Reset to first page when search text changes
    setPage(0);
  };

  // Menu handlers
  const handleMenuOpen = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
  };

  const handleColumnMenuOpen = (event) => {
    setColumnMenuAnchor(event.currentTarget);
  };

  const handleColumnMenuClose = () => {
    setColumnMenuAnchor(null);
  };

  return (
    <Box sx={{ width: '100%' }}>
      {showToolbar && (
        <Box sx={{ mb: 2 }}>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 2, mb: 1 }}>
            <Typography variant="h6" component="div">
              {title}
            </Typography>

            <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
              {/* Custom Views */}
              <CustomViews
                viewType={viewType}
                filters={activeFilters}
                onViewChange={handleApplyView}
                onSaveView={onSaveView}
                onDeleteView={onDeleteView}
                onSetDefaultView={onSetDefaultView}
                views={customViews}
                currentView={currentView}
                setCurrentView={setCurrentView}
              />

              {showSearch && (
                <TextField
                  size="small"
                  placeholder="Search..."
                  value={activeSearchText}
                  onChange={handleSearch}
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                        <SearchIcon />
                      </InputAdornment>
                    ),
                    endAdornment: activeSearchText && (
                      <InputAdornment position="end">
                        <IconButton
                          size="small"
                          onClick={() => {
                            if (onSearchChange) {
                              onSearchChange('');
                            } else {
                              setSearchText('');
                            }
                          }}
                        >
                          <ClearIcon fontSize="small" />
                        </IconButton>
                      </InputAdornment>
                    ),
                  }}
                  sx={{ minWidth: 250 }}
                />
              )}

              <Tooltip title="Filters">
                <IconButton
                  size="small"
                  color={Object.keys(activeFilters).length > 0 ? 'primary' : 'default'}
                  onClick={() => setShowFilters(!showFilters)}
                >
                  <Badge badgeContent={Object.keys(activeFilters).length} color="primary">
                    <FilterListIcon />
                  </Badge>
                </IconButton>
              </Tooltip>

              <Tooltip title="Columns">
                <IconButton
                  size="small"
                  onClick={(event) => setColumnMenuEl(event.currentTarget)}
                >
                  <ViewColumnIcon />
                </IconButton>
              </Tooltip>

              <Tooltip title="Refresh">
                <IconButton
                  size="small"
                  onClick={onRefresh}
                  disabled={loading}
                >
                  <RefreshIcon />
                </IconButton>
              </Tooltip>

              {bulkActions.length > 0 && (
                <Button
                  size="small"
                  variant="outlined"
                  onClick={(event) => setAnchorEl(event.currentTarget)}
                  endIcon={<ArrowDropDownIcon />}
                  disabled={selectedRows.length === 0}
                >
                  Actions ({selectedRows.length})
                </Button>
              )}

              <Button
                size="small"
                variant="contained"
                startIcon={<SaveIcon />}
                onClick={() => setShowSaveViewDialog(true)}
              >
                Save View
              </Button>
            </Box>
          </Box>

          {/* Active Filters */}
          {Object.keys(activeFilters).length > 0 && (
            <Box sx={{ mt: 1, display: 'flex', flexWrap: 'wrap', gap: 1 }}>
              {Object.entries(activeFilters).map(([key, value]) => {
                if (!value) return null;

                const column = columns.find(col => col.field === key);
                if (!column) return null;

                let displayValue = value;

                // Format filter value for display
                if (column.filterType === 'select' && column.filterOptions) {
                  const option = column.filterOptions.find(opt => opt.value === value);
                  if (option) displayValue = option.label;
                } else if (column.filterType === 'date') {
                  displayValue = format(new Date(value), 'MMM d, yyyy');
                } else if (column.filterType === 'range' && Array.isArray(value)) {
                  displayValue = value.join(' - ');
                }

                return (
                  <Chip
                    key={key}
                    label={`${column.headerName || key}: ${displayValue}`}
                    onDelete={() => handleFilterChange(key, '')}
                    size="small"
                    variant="outlined"
                    deleteIcon={<CloseIcon />}
                  />
                );
              })}

              <Button 
                size="small" 
                onClick={() => {
                  if (onFilterChange) {
                    onFilterChange({});
                  } else {
                    setFilters({});
                  }
                }}
                startIcon={<ClearIcon />}
              >
                Clear all
              </Button>
            </Box>
          )}
        </Box>
      )}

      <Paper variant="outlined" sx={{ width: '100%', overflow: 'hidden' }}>
        <TableContainer 
          ref={tableRef}
          sx={{ 
            maxHeight: 'calc(100vh - 300px)', 
            minHeight: 200,
            '&::-webkit-scrollbar': {
              height: 8,
              width: 8,
            },
            '&::-webkit-scrollbar-track': {
              backgroundColor: (theme) => theme.palette.grey[100],
            },
            '&::-webkit-scrollbar-thumb': {
              backgroundColor: (theme) => theme.palette.grey[400],
              borderRadius: 4,
              '&:hover': {
                backgroundColor: (theme) => theme.palette.grey[500],
              },
            },
          }}
        >
          <Table 
            stickyHeader 
            aria-labelledby="tableTitle"
            size="small"
            sx={{ 
              minWidth: 750,
              '& .MuiTableRow-hover:hover': {
                backgroundColor: (theme) => alpha(theme.palette.primary.main, 0.04),
                cursor: 'pointer',
              },
              '& .Mui-selected': {
                backgroundColor: (theme) => alpha(theme.palette.primary.main, 0.08),
                '&:hover': {
                  backgroundColor: (theme) => alpha(theme.palette.primary.main, 0.12),
                },
              },
            }}
          >
            <TableHead>
              <TableRow>
                {onSelectionChange && (
                  <TableCell padding="checkbox">
                    <Checkbox
                      indeterminate={selected.length > 0 && selected.length < data.length}
                      checked={data.length > 0 && selected.length === data.length}
                      onChange={handleSelectAllClick}
                    />
                  </TableCell>
                )}
                {columns.map((column) => (
                  <TableCell
                    key={column.field}
                    sortDirection={orderBy === column.field ? order : false}
                    sx={{ display: visibleColumns[column.field] ? 'table-cell' : 'none' }}
                  >
                    <TableSortLabel
                      active={orderBy === column.field}
                      direction={orderBy === column.field ? order : 'asc'}
                      onClick={() => column.sortable !== false && handleRequestSort(column.field)}
                    >
                      {column.headerName || column.field}
                      {orderBy === column.field ? (
                        <Box component="span" sx={visuallyHidden}>
                          {order === 'desc' ? 'sorted descending' : 'sorted ascending'}
                        </Box>
                      ) : null}
                    </TableSortLabel>
                  </TableCell>
                ))}
                {(onEdit || onDelete) && (
                  <TableCell align="right">Actions</TableCell>
                )}
              </TableRow>
            </TableHead>
            <TableBody>
              {loading ? (
                <TableRow>
                  <TableCell colSpan={columns.length + 2} align="center" sx={{ py: 3 }}>
                    Loading...
                  </TableCell>
                </TableRow>
              ) : paginatedData.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={columns.length + 2} align="center" sx={{ py: 3 }}>
                    No data available
                  </TableCell>
                </TableRow>
              ) : (
                paginatedData.map((row) => {
                  const isItemSelected = selectedRows.includes(row.id);
                  return (
                    <TableRow
                      hover
                      key={row.id}
                      selected={isItemSelected}
                      onClick={(event) => onRowClick?.(event, row)}
                      sx={{ cursor: onRowClick ? 'pointer' : 'default' }}
                    >
                      {onSelectionChange && (
                        <TableCell padding="checkbox" onClick={(e) => e.stopPropagation()}>
                          <Checkbox
                            checked={isItemSelected}
                            onChange={(event) => handleClick(event, row.id)}
                          />
                        </TableCell>
                      )}
                      {columns.map((column) => (
                        <TableCell
                          key={column.field}
                          sx={{ 
                            display: visibleColumns[column.field] ? 'table-cell' : 'none',
                            ...(column.sx || {})
                          }}
                        >
                          {column.renderCell 
                            ? column.renderCell(row) 
                            : row[column.field]}
                        </TableCell>
                      ))}
                      {(onEdit || onDelete) && (
                        <TableCell align="right" onClick={(e) => e.stopPropagation()}>
                          {onEdit && (
                            <IconButton size="small" onClick={() => onEdit(row)}>
                              <EditIcon fontSize="small" />
                            </IconButton>
                          )}
                          {onDelete && (
                            <IconButton 
                              size="small" 
                              color="error"
                              onClick={() => onDelete(row)}
                            >
                              <DeleteIcon fontSize="small" />
                            </IconButton>
                          )}
                        </TableCell>
                      )}
                    </TableRow>
                  );
                })
              )}
            </TableBody>
          </Table>
        </TableContainer>

        {showPagination && (
          <TablePagination
            rowsPerPageOptions={[10, 25, 50, 100]}
            component="div"
            count={sortedData.length}
            rowsPerPage={rowsPerPage}
            page={page}
            onPageChange={(event, newPage) => setPage(newPage)}
            onRowsPerPageChange={(event) => {
              setRowsPerPage(parseInt(event.target.value, 10));
              setPage(0);
            }}
          />
        )}
      </Paper>

      {/* Column Visibility Menu */}
      <Menu
        anchorEl={columnMenuEl}
        open={Boolean(columnMenuEl)}
        onClose={() => setColumnMenuEl(null)}
        anchorOrigin={{
          vertical: 'bottom',
          horizontal: 'right',
        }}
        transformOrigin={{
          vertical: 'top',
          horizontal: 'right',
        }}
        PaperProps={{
          sx: {
            width: 280,
            maxHeight: 400,
            overflow: 'auto',
          },
        }}
      >
        <Box sx={{ p: 1 }}>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', p: 1, pb: 1.5 }}>
            <Typography variant="subtitle2">Columns</Typography>
            <Button 
              size="small" 
              onClick={() => {
                // Show all columns
                const newVisibleColumns = {};
                columns.forEach(col => {
                  newVisibleColumns[col.field] = true;
                });
                setVisibleColumns(newVisibleColumns);
              }}
              sx={{ minWidth: 'auto', p: '2px 8px' }}
            >
              Show All
            </Button>
          </Box>

          <Divider />

          <Box sx={{ p: 1 }}>
            <TextField
              size="small"
              placeholder="Search columns..."
              fullWidth
              sx={{ mb: 1 }}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <SearchIcon fontSize="small" />
                  </InputAdornment>
                ),
              }}
            />

            <Box sx={{ maxHeight: 300, overflowY: 'auto' }}>
              {columns.map((column) => (
                <MenuItem
                  key={column.field}
                  onClick={() => {
                    setVisibleColumns(prev => ({
                      ...prev,
                      [column.field]: !prev[column.field]
                    }));
                  }}
                  dense
                  sx={{
                    borderRadius: 1,
                    '&:hover': {
                      backgroundColor: 'action.hover',
                    },
                  }}
                >
                  <Checkbox
                    size="small"
                    checked={visibleColumns[column.field] !== false}
                    sx={{ p: 0.5, mr: 1.5 }}
                  />
                  <Box>
                    <Typography variant="body2">
                      {column.headerName || column.field}
                    </Typography>
                    {column.description && (
                      <Typography variant="caption" color="text.secondary">
                        {column.description}
                      </Typography>
                    )}
                  </Box>
                </MenuItem>
              ))}
            </Box>
          </Box>
        </Box>
      </Menu>

      {showFilters && (
        <Box sx={{ mb: 2, border: '1px solid', borderColor: 'divider', borderRadius: 1, overflow: 'hidden' }}>
          <Tabs 
            value={activeFilterTab} 
            onChange={handleFilterTabChange}
            variant="scrollable"
            scrollButtons="auto"
            sx={{ borderBottom: '1px solid', borderColor: 'divider', bgcolor: 'background.paper' }}
          >
            <Tab label="Quick Filters" />
            <Tab label="Advanced" />
          </Tabs>

          <Box sx={{ p: 2, bgcolor: 'background.paper' }}>
            {activeFilterTab === 0 && (
              <Grid container spacing={2}>
                {columns
                  .filter(column => column.filterable && column.filterType !== 'custom')
                  .map((column) => (
                    <Grid item xs={12} sm={6} md={4} lg={3} key={column.field}>
                      <FormControl fullWidth size="small">
                        <InputLabel>{column.headerName}</InputLabel>
                        {column.filterType === 'select' ? (
                          <Select
                            value={activeFilters[column.field] || ''}
                            onChange={(e) => handleFilterChange(column.field, e.target.value)}
                            input={<OutlinedInput label={column.headerName} />}
                          >
                            <MenuItem value="">
                              <em>All</em>
                            </MenuItem>
                            {column.filterOptions?.map((option) => (
                              <MenuItem key={option.value} value={option.value}>
                                {option.label}
                              </MenuItem>
                            )) || []}
                          </Select>
                        ) : column.filterType === 'date' ? (
                          <TextField
                            type="date"
                            value={activeFilters[column.field] || ''}
                            onChange={(e) => handleFilterChange(column.field, e.target.value)}
                            size="small"
                            InputLabelProps={{
                              shrink: true,
                            }}
                          />
                        ) : column.filterType === 'range' ? (
                          <Box sx={{ display: 'flex', gap: 1 }}>
                            <TextField
                              type="number"
                              placeholder="Min"
                              value={activeFilters[column.field]?.[0] || ''}
                              onChange={(e) => {
                                const newValue = [e.target.value, activeFilters[column.field]?.[1]];
                                handleFilterChange(column.field, newValue);
                              }}
                              size="small"
                              fullWidth
                            />
                            <TextField
                              type="number"
                              placeholder="Max"
                              value={activeFilters[column.field]?.[1] || ''}
                              onChange={(e) => {
                                const newValue = [activeFilters[column.field]?.[0], e.target.value];
                                handleFilterChange(column.field, newValue);
                              }}
                              size="small"
                              fullWidth
                            />
                          </Box>
                        ) : (
                          <TextField
                            value={activeFilters[column.field] || ''}
                            onChange={(e) => handleFilterChange(column.field, e.target.value)}
                            size="small"
                            placeholder={`Filter by ${column.headerName}`}
                          />
                        )}
                      </FormControl>
                    </Grid>
                  ))}
              </Grid>
            )}

            {activeFilterTab === 1 && (
              <Box>
                <Typography variant="subtitle2" gutterBottom>
                  Custom Filters
                </Typography>
                <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap' }}>
                  {columns
                    .filter(column => column.filterType === 'custom' && column.customFilter)
                    .map((column) => (
                      <Card key={column.field} variant="outlined" sx={{ minWidth: 275 }}>
                        <CardContent>
                          <Typography variant="subtitle2" gutterBottom>
                            {column.headerName}
                          </Typography>
                          {column.customFilterComponent ? (
                            <column.customFilterComponent 
                              value={activeFilters[column.field]} 
                              onChange={(value) => handleFilterChange(column.field, value)}
                            />
                          ) : (
                            <Typography variant="body2" color="text.secondary">
                              Custom filter applied
                            </Typography>
                          )}
                        </CardContent>
                      </Card>
                    ))}
                </Box>
              </Box>
            )}
          </Box>
        </Box>
      )}

      {/* Bulk Actions Menu */}
      <Menu
        anchorEl={anchorEl}
        open={Boolean(anchorEl)}
        onClose={() => setAnchorEl(null)}
        anchorOrigin={{
          vertical: 'bottom',
          horizontal: 'right',
        }}
        transformOrigin={{
          vertical: 'top',
          horizontal: 'right',
        }}
      >
        <Box sx={{ py: 0.5 }}>
          <Box sx={{ px: 2, py: 1 }}>
            <Typography variant="subtitle2" color="text.secondary">
              {selectedRows.length} selected
            </Typography>
          </Box>

          <Divider />

          {bulkActions.map((action, index) => (
            <MenuItem 
              key={index} 
              onClick={() => {
                if (onBulkAction) {
                  onBulkAction(action.action || action, selectedRows);
                }
                setAnchorEl(null);
              }}
              sx={{
                ...(action.color ? { color: `${action.color}.main` } : {}),
                '&:hover': {
                  backgroundColor: action.color ? `${action.color}.50` : 'action.hover',
                },
              }}
            >
              <Box sx={{ display: 'flex', alignItems: 'center', width: '100%' }}>
                {action.icon && React.cloneElement(action.icon, { sx: { mr: 1.5, fontSize: 20 } })}
                <Box>
                  <Typography variant="body2">{action.label}</Typography>
                  {action.description && (
                    <Typography variant="caption" color="text.secondary">
                      {action.description}
                    </Typography>
                  )}
                </Box>
              </Box>
            </MenuItem>
          ))}

          <Divider />

          <MenuItem 
            onClick={() => {
              setSelected([]);
              setAnchorEl(null);
            }}
            sx={{
              color: 'text.secondary',
              '&:hover': {
                backgroundColor: 'action.hover',
              },
            }}
          >
            <Box sx={{ display: 'flex', alignItems: 'center', width: '100%' }}>
              <ClearIcon fontSize="small" sx={{ mr: 1.5, fontSize: 20 }} />
              <Typography variant="body2">Clear selection</Typography>
            </Box>
          </MenuItem>
        </Box>
      </Menu>

      {/* Save View Dialog */}
      <Dialog 
        open={showSaveViewDialog} 
        onClose={() => setShowSaveViewDialog(false)}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>Save Current View</DialogTitle>
        <DialogContent>
          <TextField
            autoFocus
            margin="dense"
            label="View name"
            fullWidth
            variant="outlined"
            value={viewName}
            onChange={(e) => setViewName(e.target.value)}
            sx={{ mb: 2 }}
          />

          <FormControlLabel
            control={
              <MuiCheckbox
                checked={isPublicView}
                onChange={(e) => setIsPublicView(e.target.checked)}
                color="primary"
              />
            }
            label="Make this view available to all users"
          />

          <Box sx={{ mt: 2, p: 2, bgcolor: 'background.default', borderRadius: 1 }}>
            <Typography variant="subtitle2" gutterBottom>
              View Settings
            </Typography>

            <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 2, mt: 1 }}>
              <Box>
                <Typography variant="caption" color="text.secondary" display="block">
                  Filters
                </Typography>
                <Typography variant="body2">
                  {Object.keys(activeFilters).length} active
                </Typography>
              </Box>

              <Box>
                <Typography variant="caption" color="text.secondary" display="block">
                  Sort
                </Typography>
                <Typography variant="body2">
                  {orderBy ? `${orderBy} (${order})` : 'None'}
                </Typography>
              </Box>

              <Box>
                <Typography variant="caption" color="text.secondary" display="block">
                  Visible Columns
                </Typography>
                <Typography variant="body2">
                  {Object.values(visibleColumns).filter(v => v).length} of {columns.length}
                </Typography>
              </Box>
            </Box>
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setShowSaveViewDialog(false)}>
            Cancel
          </Button>
          <Button 
            onClick={handleSaveView} 
            variant="contained" 
            color="primary"
            disabled={!viewName.trim()}
            startIcon={<SaveIcon />}
          >
            Save View
          </Button>
        </DialogActions>
      </Dialog>

      {/* Loading Overlay */}
      {loading && (
        <Box
          sx={{
            position: 'absolute',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: 'rgba(255, 255, 255, 0.7)',
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center',
            zIndex: 10,
          }}
        >
          <CircularProgress />
        </Box>
      )}
    </Box>
  );
};

// Add default props for better TypeScript/PropTypes support
DataTable.defaultProps = {
  showSearch: true,
  showToolbar: true,
  showPagination: true,
  loading: false,
  filters: {},
  selectedRows: [],
  bulkActions: [],
  viewType: 'default',
  customViews: [],
};

// Add prop types validation
DataTable.propTypes = {
  columns: PropTypes.arrayOf(
    PropTypes.shape({
      field: PropTypes.string.isRequired,
      headerName: PropTypes.string,
      sortable: PropTypes.bool,
      filterable: PropTypes.bool,
      filterType: PropTypes.oneOf(['select', 'text', 'date', 'range', 'custom']),
      filterOptions: PropTypes.arrayOf(
        PropTypes.shape({
          value: PropTypes.any.isRequired,
          label: PropTypes.string.isRequired,
        })
      ),
      customFilter: PropTypes.func,
      customFilterComponent: PropTypes.elementType,
      renderCell: PropTypes.func,
      width: PropTypes.oneOfType([PropTypes.number, PropTypes.string]),
      flex: PropTypes.number,
      align: PropTypes.oneOf(['left', 'center', 'right']),
      headerAlign: PropTypes.oneOf(['left', 'center', 'right']),
      description: PropTypes.string,
    })
  ).isRequired,
  data: PropTypes.arrayOf(PropTypes.object).isRequired,
  onRowClick: PropTypes.func,
  onEdit: PropTypes.func,
  onDelete: PropTypes.func,
  onRefresh: PropTypes.func,
  onSelectionChange: PropTypes.func,
  onBulkAction: PropTypes.func,
  loading: PropTypes.bool,
  title: PropTypes.string,
  showSearch: PropTypes.bool,
  showToolbar: PropTypes.bool,
  showPagination: PropTypes.bool,
  searchText: PropTypes.string,
  onSearchChange: PropTypes.func,
  filters: PropTypes.object,
  onFilterChange: PropTypes.func,
  selectedRows: PropTypes.array,
  dateRange: PropTypes.shape({
    start: PropTypes.instanceOf(Date),
    end: PropTypes.instanceOf(Date),
  }),
  onDateRangeChange: PropTypes.func,
  bulkActions: PropTypes.arrayOf(
    PropTypes.oneOfType([
      PropTypes.shape({
        label: PropTypes.string.isRequired,
        action: PropTypes.oneOfType([PropTypes.string, PropTypes.func]).isRequired,
        icon: PropTypes.element,
        color: PropTypes.string,
        description: PropTypes.string,
      }),
      PropTypes.string,
    ])
  ),
  viewType: PropTypes.string,
  onViewChange: PropTypes.func,
  onSaveView: PropTypes.func,
  onDeleteView: PropTypes.func,
  onSetDefaultView: PropTypes.func,
  customViews: PropTypes.array,
  currentView: PropTypes.object,
  setCurrentView: PropTypes.func,
};

export default React.memo(DataTable);
